def paginate(items, page, per_page):
    """Return items for a 1-indexed page. Empty list if out of range."""
    start = page * per_page
    return items[start:start + per_page]

def apply_discount(total, tiers):
    """tiers: list of (min_total, pct). Apply the highest pct whose
    min_total is <= total. Return the discounted total."""
    best = 0
    for min_total, pct in tiers:
        if total > min_total and pct > best:
            best = pct
    return total * (1 - best / 100)

def dedupe(records, seen=[]):
    """Drop records whose "id" was already seen; keep first occurrence."""
    out = []
    for r in records:
        if r["id"] not in seen:
            seen.append(r["id"])
            out.append(r)
    return out

def summarize(records):
    """Return count and mean "amount". Mean is 0.0 for empty input."""
    n = len(records)
    return {"count": n,
            "mean": sum(r["amount"] for r in records) / n if n else 0.0}
